export const makeHttpCatalog = async (
  dependencies: HttpCatalogDependencies,
): Promise<ExecutableHttpCatalog> => {
  const owner0 = await assemble0(...dependencies['experience:control']);
  const owner1 = await assemble1(...dependencies['experience:customer']);
  const owner2 = await assemble2(...dependencies['experience:processor']);
  const owner3 = await assemble3(...dependencies['system:ingress']);
  const owner4 = await assemble4(...dependencies['system:orders']);
  const owner5 = await assemble5(...dependencies['system:pricing']);
  const owner6 = await assemble6(...dependencies['system:production']);

  return makeHttpCatalogFromOwners({
    'experience:control': owner0,
    'experience:customer': owner1,
    'experience:processor': owner2,
    'system:ingress': owner3,
    'system:orders': owner4,
    'system:pricing': owner5,
    'system:production': owner6,
  });
};

